+at::Tensor maybe_cast_dtype(const at::Tensor &tensor, at::ScalarType dtype) {
+  at::Tensor out = tensor;
+  if (out.scalar_type() != dtype) {
+    out = out.to(out.options().dtype(dtype));
+  }
+  return out;
+}
